Repository: Know Meet (React 19 web meeting app on LiveKit). Diff base: main; head: 11ecd347 (branch feat/web-conferencing-features). This is packet 5 of 7, feature area: local recording pipeline, OPFS storage, recording consent domain. Other areas are reviewed in separate packets; do not report a defect solely because code referenced from another area is not shown.

Acceptance criteria (phase goals). Participants can: share a screen and stop; send chat to everyone or privately to one participant; blur or replace their background; pick microphone, camera and speaker with levels and preview, before and during a meeting; get an "Enable audio" prompt when autoplay is blocked. Local history (PGlite idb://) and local recordings stay on the device. Recording needs consent. Secrets stay server-side and clients get short-lived tokens. No `any` in TypeScript. Tauri calls are guarded by isTauri(). Flat UI with no borders, outlines or strokes; WCAG 2.2 AA.

Review the following unified diff:

diff --git a/apps/web/src/infrastructure/recording/audio-mixer.ts b/apps/web/src/infrastructure/recording/audio-mixer.ts
new file mode 100644
index 00000000..dc4646a5
--- /dev/null
+++ b/apps/web/src/infrastructure/recording/audio-mixer.ts
@@ -0,0 +1,86 @@
+// TJ-ARCH-MOB-001 compliant
+
+/**
+ * Mixes every audio source of the meeting into one track for the recorder: a Web Audio
+ * graph with one gain node per source, all into one `MediaStreamAudioDestinationNode`.
+ * The mix is never connected to the speakers, so recording adds no echo.
+ */
+export interface AudioMixer {
+  /** The mixed audio, one track. */
+  readonly stream: MediaStream;
+  /**
+   * Sets or replaces the source under `key`. A stream without live audio tracks removes
+   * it. The same stream again changes nothing but the gain.
+   */
+  setSource(key: string, stream: MediaStream | null, gain: number): void;
+  /** Removes every source whose key is not in `keys`. */
+  keepOnly(keys: ReadonlySet<string>): void;
+  /** Starts the context if the browser left it suspended. */
+  resume(): Promise<void>;
+  close(): Promise<void>;
+}
+
+interface Source {
+  readonly signature: string;
+  readonly node: MediaStreamAudioSourceNode;
+  readonly gain: GainNode;
+}
+
+function liveAudioTracks(stream: MediaStream): MediaStreamTrack[] {
+  return stream.getAudioTracks().filter((track) => track.readyState === "live");
+}
+
+/** Changes when a track is added, replaced or ends, so a rebound element is noticed. */
+function signatureOf(tracks: readonly MediaStreamTrack[]): string {
+  return tracks.map((track) => track.id).join(",");
+}
+
+export function createAudioMixer(): AudioMixer {
+  const context = new AudioContext({ latencyHint: "playback" });
+  const destination = context.createMediaStreamDestination();
+  const sources = new Map<string, Source>();
+
+  const remove = (key: string): void => {
+    const source = sources.get(key);
+    if (source === undefined) return;
+    sources.delete(key);
+    source.node.disconnect();
+    source.gain.disconnect();
+  };
+
+  return {
+    stream: destination.stream,
+    setSource: (key, stream, gainValue) => {
+      const tracks = stream === null ? [] : liveAudioTracks(stream);
+      if (tracks.length === 0) {
+        remove(key);
+        return;
+      }
+      const signature = signatureOf(tracks);
+      const existing = sources.get(key);
+      if (existing !== undefined && existing.signature === signature) {
+        existing.gain.gain.value = gainValue;
+        return;
+      }
+      remove(key);
+      // A copy holding only the audio tracks, so the video of the same element is untouched.
+      const node = context.createMediaStreamSource(new MediaStream(tracks));
+      const gain = context.createGain();
+      gain.gain.value = gainValue;
+      node.connect(gain);
+      gain.connect(destination);
+      sources.set(key, { signature, node, gain });
+    },
+    keepOnly: (keys) => {
+      for (const key of [...sources.keys()]) if (!keys.has(key)) remove(key);
+    },
+    resume: async () => {
+      if (context.state === "suspended") await context.resume().catch(() => undefined);
+    },
+    close: async () => {
+      for (const key of [...sources.keys()]) remove(key);
+      for (const track of destination.stream.getTracks()) track.stop();
+      await context.close().catch(() => undefined);
+    },
+  };
+}
diff --git a/apps/web/src/infrastructure/recording/composite-pipeline.ts b/apps/web/src/infrastructure/recording/composite-pipeline.ts
new file mode 100644
index 00000000..8dbc816e
--- /dev/null
+++ b/apps/web/src/infrastructure/recording/composite-pipeline.ts
@@ -0,0 +1,172 @@
+// TJ-ARCH-MOB-001 compliant
+import type { RealtimeRoom } from "@know-meet/application";
+import { type AudioMixer, createAudioMixer } from "./audio-mixer";
+import { type FrameClock, startFrameClock } from "./frame-clock";
+import { createFrameCompositor, readCompositePalette } from "./frame-compositor";
+import {
+  type CaptureMicrophone,
+  createLocalMicrophoneFeed,
+  LOCAL_MICROPHONE_KEY,
+} from "./local-microphone";
+import { createMediaBindings } from "./media-bindings";
+import {
+  AUDIO_BITS_PER_SECOND,
+  COMPOSITE_FPS,
+  COMPOSITE_HEIGHT,
+  COMPOSITE_WIDTH,
+  RECORDER_TIMESLICE_MS,
+  VIDEO_BITS_PER_SECOND,
+} from "./recording-constants";
+import type { ChosenFormat } from "./recording-support";
+
+export interface CompositePipelineOptions {
+  readonly room: RealtimeRoom;
+  readonly format: ChosenFormat;
+  readonly captureMicrophone: CaptureMicrophone;
+  /** One encoded chunk, in order, about every second. */
+  readonly onChunk: (chunk: Blob) => void;
+  /** The encoder failed; the pipeline is not usable afterwards. */
+  readonly onError: () => void;
+}
+
+/**
+ * The picture and sound of one recording (wc10 task 10.1): a canvas grid of the room's
+ * video tiles and one mixed audio track, encoded by `MediaRecorder`.
+ *
+ *   room.attachMedia ──> hidden <video> per camera / share ──> canvas grid ──┐
+ *                                                                              ├─> MediaStream ─> MediaRecorder ─> onChunk
+ *   room.attachMedia ──> hidden <audio> per remote mic ──> WebAudio mix ──────┤
+ *   local microphone (own capture, gain 0 while muted) ──────────────────────┘
+ *
+ * The room is only read through `RealtimeRoom`, so no media SDK is imported here.
+ */
+export interface CompositePipeline {
+  /** Starts drawing and encoding. Call once. */
+  start(): void;
+  /**
+   * Stops drawing and encoding and resolves once the last chunk was handed to `onChunk`.
+   * Safe to call twice.
+   */
+  finish(): Promise<void>;
+  /** Releases the elements, the audio graph and the capture. Call after `finish`. */
+  dispose(): Promise<void>;
+}
+
+const FINISH_TIMEOUT_MS = 5000;
+/** Audio sources are re-read this often, to notice a track that was replaced. */
+const AUDIO_SYNC_FRAMES = COMPOSITE_FPS * 2;
+
+export function createCompositePipeline(options: CompositePipelineOptions): CompositePipeline {
+  const { room } = options;
+  const canvas = document.createElement("canvas");
+  canvas.width = COMPOSITE_WIDTH;
+  canvas.height = COMPOSITE_HEIGHT;
+  const compositor = createFrameCompositor(canvas, readCompositePalette(document.documentElement));
+  const bindings = createMediaBindings(room);
+  const mixer: AudioMixer = createAudioMixer();
+  const microphone = createLocalMicrophoneFeed(mixer, options.captureMicrophone);
+
+  const syncAudio = (): void => {
+    const keys = new Set<string>([LOCAL_MICROPHONE_KEY]);
+    for (const media of bindings.current()) {
+      if (media.medium !== "audio") continue;
+      keys.add(media.key);
+      const source = media.element.srcObject;
+      mixer.setSource(media.key, source instanceof MediaStream ? source : null, 1);
+    }
+    mixer.keepOnly(keys);
+  };
+
+  const syncRoom = (): void => {
+    const snapshot = room.getSnapshot();
+    bindings.sync(snapshot);
+    microphone.sync(snapshot);
+    syncAudio();
+  };
+
+  syncRoom();
+  compositor.draw(bindings.current());
+
+  const videoTrack = canvas.captureStream(COMPOSITE_FPS).getVideoTracks();
+  const stream = new MediaStream([...videoTrack, ...mixer.stream.getAudioTracks()]);
+  let recorder: MediaRecorder;
+  try {
+    recorder = new MediaRecorder(stream, {
+      mimeType: options.format.mimeType,
+      videoBitsPerSecond: VIDEO_BITS_PER_SECOND,
+      audioBitsPerSecond: AUDIO_BITS_PER_SECOND,
+    });
+  } catch (error) {
+    // The encoder refused the format: release what was opened above before reporting it.
+    microphone.dispose();
+    bindings.dispose();
+    for (const track of stream.getTracks()) track.stop();
+    void mixer.close();
+    throw error;
+  }
+  recorder.addEventListener("dataavailable", (event) => {
+    if (event.data.size > 0) options.onChunk(event.data);
+  });
+  recorder.addEventListener("error", () => options.onError());
+
+  let clock: FrameClock | null = null;
+  let frames = 0;
+  let unsubscribe: (() => void) | null = null;
+  let finishing: Promise<void> | null = null;
+  let disposed = false;
+
+  const stopClock = (): void => {
+    clock?.stop();
+    clock = null;
+    unsubscribe?.();
+    unsubscribe = null;
+  };
+
+  return {
+    start: () => {
+      void mixer.resume();
+      unsubscribe = room.subscribe(syncRoom);
+      clock = startFrameClock(COMPOSITE_FPS, () => {
+        frames += 1;
+        if (frames % AUDIO_SYNC_FRAMES === 0) syncAudio();
+        compositor.draw(bindings.current());
+      });
+      recorder.start(RECORDER_TIMESLICE_MS);
+    },
+    finish: () => {
+      finishing ??= new Promise<void>((resolve) => {
+        stopClock();
+        if (recorder.state === "inactive") {
+          resolve();
+          return;
+        }
+        const timer = setTimeout(resolve, FINISH_TIMEOUT_MS);
+        // The encoder fires its last `dataavailable` before `stop`.
+        recorder.addEventListener(
+          "stop",
+          () => {
+            clearTimeout(timer);
+            resolve();
+          },
+          { once: true },
+        );
+        try {
+          recorder.stop();
+        } catch {
+          clearTimeout(timer);
+          resolve();
+        }
+      });
+      return finishing;
+    },
+    dispose: async () => {
+      if (disposed) return;
+      disposed = true;
+      stopClock();
+      microphone.dispose();
+      bindings.dispose();
+      for (const track of stream.getTracks()) track.stop();
+      await mixer.close();
+    },
+  };
+}
diff --git a/apps/web/src/infrastructure/recording/composite-recorder.ts b/apps/web/src/infrastructure/recording/composite-recorder.ts
new file mode 100644
index 00000000..cedd5941
--- /dev/null
+++ b/apps/web/src/infrastructure/recording/composite-recorder.ts
@@ -0,0 +1,211 @@
+// TJ-ARCH-MOB-001 compliant
+import type { LocalRecorder, RealtimeRoom } from "@know-meet/application";
+import {
+  conferencingErrors,
+  err,
+  ok,
+  type RecorderFailed,
+  type RecorderFailureReason,
+  type RecordingRequestId,
+  type Result,
+  type Support,
+} from "@know-meet/domain";
+import { type CompositePipeline, createCompositePipeline } from "./composite-pipeline";
+import type { RecordingIndexWriter } from "./library-types";
+import { type CaptureMicrophone, captureMicrophoneFromBrowser } from "./local-microphone";
+import { MIN_FREE_BYTES, recordingLockName } from "./recording-constants";
+import { detectRecordingSupport, pickRecordingFormat } from "./recording-support";
+import { estimateStorage } from "./store/recording-files";
+import { createOpfsWriter, type RecordingWriter } from "./writer/opfs-writer-client";
+import type { WriterFailure } from "./writer/writer-protocol";
+
+/** A `LocalRecorder` that also says which recording this tab is writing. */
+export interface CompositeRecorder extends LocalRecorder {
+  activeRequestId(): RecordingRequestId | null;
+}
+
+export interface CompositeRecorderOptions {
+  readonly room: RealtimeRoom;
+  readonly index: RecordingIndexWriter;
+  /** The room code of the meeting being recorded, for the index. */
+  readonly roomCode: () => string | null;
+  readonly now?: () => number;
+  /** Free bytes the browser reports, or null when it will not say. */
+  readonly freeBytes?: () => Promise<number | null>;
+  readonly createWriter?: () => RecordingWriter;
+  readonly captureMicrophone?: CaptureMicrophone;
+}
+
+type EndReason = "stopped" | "storage-full" | "failed";
+
+interface Active {
+  readonly id: RecordingRequestId;
+  readonly pipeline: CompositePipeline;
+  readonly writer: RecordingWriter;
+  readonly stopListening: () => void;
+  /** Chunks reach the writer in encoder order even though `arrayBuffer()` is asynchronous. */
+  chunks: Promise<void>;
+  finalising: Promise<void> | null;
+}
+
+async function defaultFreeBytes(): Promise<number | null> {
+  const { usedBytes, quotaBytes } = await estimateStorage();
+  return usedBytes === null || quotaBytes === null ? null : quotaBytes - usedBytes;
+}
+
+function failureFor(reason: WriterFailure): RecorderFailureReason {
+  return reason === "quota-exceeded"
+    ? "quota-exceeded"
+    : reason === "storage-unavailable"
+      ? "storage-unavailable"
+      : "failed";
+}
+
+/**
+ * The local recorder (wc10 tasks 10.1 and 10.2): composites the room into one picture and
+ * one mix (`composite-pipeline`) and appends the encoded chunks to a file in OPFS through
+ * a worker (`writer`), noting it in the recordings index. Only the recording consent use
+ * cases start or stop it.
+ *
+ * - `stop` always finalises and keeps what was written; with nothing recording it succeeds.
+ * - A write that fails (storage full, file system lost) or an encoder error ends the
+ *   recording by itself: the file is closed with everything written so far, the index row
+ *   is closed with how it ended, then the `onStoppedItself` listeners hear why.
+ * - If the tab dies instead, no row is ever closed. The writer's lock goes with the tab,
+ *   and the library lists the recording as incomplete, with its file intact.
+ * - Nothing is sent anywhere.
+ */
+export function createCompositeRecorder(options: CompositeRecorderOptions): CompositeRecorder {
+  const now = options.now ?? Date.now;
+  const freeBytes = options.freeBytes ?? defaultFreeBytes;
+  const createWriter = options.createWriter ?? createOpfsWriter;
+  const captureMicrophone = options.captureMicrophone ?? captureMicrophoneFromBrowser;
+  const support: Support = detectRecordingSupport();
+  const listeners = new Set<(reason: RecorderFailureReason) => void>();
+  let active: Active | null = null;
+  let starting = false;
+
+  const finalise = (session: Active, endReason: EndReason): Promise<void> => {
+    session.finalising ??= (async () => {
+      try {
+        session.stopListening();
+        await session.pipeline.finish();
+        await session.chunks;
+        const size = await session.writer.close();
+        await session.pipeline.dispose().catch(() => undefined);
+        await options.index.finish({ id: session.id, endedAt: now(), sizeBytes: size, endReason });
+      } finally {
+        if (active === session) active = null;
+      }
+    })();
+    return session.finalising;
+  };
+
+  const stopItself = async (
+    session: Active,
+    endReason: Exclude<EndReason, "stopped">,
+    reason: RecorderFailureReason,
+  ): Promise<void> => {
+    if (session.finalising !== null) return;
+    await finalise(session, endReason);
+    for (const listener of [...listeners]) {
+      try {
+        listener(reason);
+      } catch {
+        // A listener that throws must not keep the others from hearing it.
+      }
+    }
+  };
+
+  const start = async (requestId: RecordingRequestId): Promise<Result<void, RecorderFailed>> => {
+    if (support === "unsupported") return err(conferencingErrors.recorderFailed("unsupported"));
+    const format = pickRecordingFormat();
+    if (format === null) return err(conferencingErrors.recorderFailed("unsupported"));
+    if (active !== null || starting) return err(conferencingErrors.recorderFailed("failed"));
+    starting = true;
+    try {
+      const free = await freeBytes();
+      if (free !== null && free < MIN_FREE_BYTES) {
+        return err(conferencingErrors.recorderFailed("quota-exceeded"));
+      }
+      const writer = createWriter();
+      const fileName = `${requestId}.${format.extension}`;
+      const opened = await writer.open(fileName, recordingLockName(requestId));
+      if (!opened.ok) return opened;
+
+      let session: Active;
+      try {
+        const pipeline = createCompositePipeline({
+          room: options.room,
+          format,
+          captureMicrophone,
+          onChunk: (chunk) => {
+            const current = session;
+            current.chunks = current.chunks
+              .then(() => chunk.arrayBuffer())
+              .then((buffer) => writer.append(buffer))
+              .catch(() => undefined);
+          },
+          onError: () => void stopItself(session, "failed", "failed"),
+        });
+        const stopListening = writer.onFailed(
+          (reason) =>
+            void stopItself(
+              session,
+              reason === "quota-exceeded" ? "storage-full" : "failed",
+              failureFor(reason),
+            ),
+        );
+        session = {
+          id: requestId,
+          pipeline,
+          writer,
+          stopListening,
+          chunks: Promise.resolve(),
+          finalising: null,
+        };
+      } catch {
+        await writer.close();
+        return err(conferencingErrors.recorderFailed("failed"));
+      }
+
+      active = session;
+      await options.index.begin({
+        id: requestId,
+        roomCode: options.roomCode(),
+        fileName,
+        mimeType: format.mimeType,
+        startedAt: now(),
+      });
+      // The writer can fail while the index row is being made; then it already finalised.
+      if (session.finalising !== null) return err(conferencingErrors.recorderFailed("failed"));
+      try {
+        session.pipeline.start();
+      } catch {
+        await finalise(session, "failed");
+        return err(conferencingErrors.recorderFailed("failed"));
+      }
+      return ok(undefined);
+    } finally {
+      starting = false;
+    }
+  };
+
+  return {
+    support,
+    activeRequestId: () => active?.id ?? null,
+    start,
+    stop: async () => {
+      const session = active;
+      if (session === null) return ok(undefined);
+      await finalise(session, "stopped");
+      return ok(undefined);
+    },
+    onStoppedItself: (listener) => {
+      listeners.add(listener);
+      return () => {
+        listeners.delete(listener);
+      };
+    },
+  };
+}
diff --git a/apps/web/src/infrastructure/recording/desired-media.ts b/apps/web/src/infrastructure/recording/desired-media.ts
new file mode 100644
index 00000000..96dbc27c
--- /dev/null
+++ b/apps/web/src/infrastructure/recording/desired-media.ts
@@ -0,0 +1,64 @@
+// TJ-ARCH-MOB-001 compliant
+import type { MediaTarget, RoomSnapshot } from "@know-meet/application";
+
+/** One medium the recording needs from the room, as the snapshot says it exists now. */
+export interface DesiredMedia {
+  /** Stable while the medium exists; the binding is kept as long as the key is. */
+  readonly key: string;
+  readonly target: MediaTarget;
+  readonly medium: "video" | "audio";
+  /** The name drawn on the tile, empty for audio. */
+  readonly label: string;
+}
+
+/**
+ * Which media to bind for the recording: every participant's camera (a tile even when the
+ * camera is off), every screen share this client receives (a tile), and the remote
+ * microphones and share audio (mixed, not drawn).
+ *
+ * The local microphone is not here on purpose: the room never hands a participant their
+ * own microphone through `attachMedia`, so it is captured separately (`local-microphone`).
+ */
+export function desiredMedia(snapshot: RoomSnapshot): readonly DesiredMedia[] {
+  const media: DesiredMedia[] = [];
+  const names = new Map<string, string>();
+  if (snapshot.local !== null) names.set(snapshot.local.identity, snapshot.local.displayName);
+  for (const remote of snapshot.remotes) names.set(remote.identity, remote.displayName);
+
+  const people = [...(snapshot.local === null ? [] : [snapshot.local]), ...snapshot.remotes];
+  for (const person of people) {
+    media.push({
+      key: `camera:${person.identity}`,
+      target: { identity: person.identity, kind: "camera" },
+      medium: "video",
+      label: person.displayName,
+    });
+    if (person.kind === "remote") {
+      media.push({
+        key: `microphone:${person.identity}`,
+        target: { identity: person.identity, kind: "microphone" },
+        medium: "audio",
+        label: "",
+      });
+    }
+  }
+  for (const share of snapshot.screenShares) {
+    if (!share.subscribed) continue;
+    const name = names.get(share.identity) ?? "";
+    media.push({
+      key: `screen-share:${share.identity}`,
+      target: { identity: share.identity, kind: "screen-share" },
+      medium: "video",
+      label: name,
+    });
+    if (share.hasAudio && !share.isLocal) {
+      media.push({
+        key: `screen-share-audio:${share.identity}`,
+        target: { identity: share.identity, kind: "screen-share-audio" },
+        medium: "audio",
+        label: "",
+      });
+    }
+  }
+  return media;
+}
diff --git a/apps/web/src/infrastructure/recording/frame-clock.ts b/apps/web/src/infrastructure/recording/frame-clock.ts
new file mode 100644
index 00000000..963f149b
--- /dev/null
+++ b/apps/web/src/infrastructure/recording/frame-clock.ts
@@ -0,0 +1,41 @@
+// TJ-ARCH-MOB-001 compliant
+
+export interface FrameClock {
+  stop(): void;
+}
+
+/**
+ * Calls `onFrame` about `fps` times a second until stopped. Driven by a worker timer so
+ * frames keep coming while the tab is in the background; falls back to a page timer where
+ * a worker cannot start.
+ */
+export function startFrameClock(fps: number, onFrame: () => void): FrameClock {
+  const interval = Math.round(1000 / fps);
+  let worker: Worker | null = null;
+  let fallback: ReturnType<typeof setInterval> | null = null;
+  try {
+    worker = new Worker(new URL("./frame-tick-worker.ts", import.meta.url), {
+      type: "module",
+      name: "know-meet-recording-clock",
+    });
+    worker.addEventListener("message", onFrame);
+    worker.addEventListener("error", () => {
+      worker?.terminate();
+      worker = null;
+      fallback ??= setInterval(onFrame, interval);
+    });
+    worker.postMessage(interval);
+  } catch {
+    worker = null;
+    fallback = setInterval(onFrame, interval);
+  }
+  return {
+    stop: () => {
+      worker?.postMessage("stop");
+      worker?.terminate();
+      worker = null;
+      if (fallback !== null) clearInterval(fallback);
+      fallback = null;
+    },
+  };
+}
diff --git a/apps/web/src/infrastructure/recording/frame-compositor.ts b/apps/web/src/infrastructure/recording/frame-compositor.ts
new file mode 100644
index 00000000..c262ba2b
--- /dev/null
+++ b/apps/web/src/infrastructure/recording/frame-compositor.ts
@@ -0,0 +1,146 @@
+// TJ-ARCH-MOB-001 compliant
+
+import { computeGridLayout, type TileRect } from "./grid-layout";
+import type { BoundMedia } from "./media-bindings";
+
+/** Colours and font for what is drawn into the recording, read from the design tokens. */
+export interface CompositePalette {
+  readonly background: string;
+  readonly tile: string;
+  readonly text: string;
+  readonly tagBackground: string;
+  readonly font: string;
+}
+
+const GAP = 12;
+const TAG_HEIGHT = 28;
+const TAG_PADDING = 10;
+
+/**
+ * The media tokens are the same in both themes (video sits on black), so the recording
+ * looks the same whatever theme the recorder uses. Missing tokens fall back to the
+ * browser's own system colours, never to colours chosen here.
+ */
+export function readCompositePalette(root: HTMLElement): CompositePalette {
+  const style = getComputedStyle(root);
+  const read = (name: string, fallback: string): string => {
+    const value = style.getPropertyValue(name).trim();
+    return value === "" ? fallback : value;
+  };
+  return {
+    background: read("--media-bg", "Canvas"),
+    tile: read("--media-tag-bg", "Canvas"),
+    text: read("--on-media", "CanvasText"),
+    tagBackground: read("--media-tag-bg", "Canvas"),
+    font: read("--font-body", "sans-serif"),
+  };
+}
+
+export interface FrameCompositor {
+  /** Draws the current grid of the given tiles. Call once per frame. */
+  draw(tiles: readonly BoundMedia[]): void;
+}
+
+function initialsOf(name: string): string {
+  const parts = name
+    .trim()
+    .split(/\s+/)
+    .filter((part) => part !== "");
+  const letters = parts.slice(0, 2).map((part) => part.slice(0, 1).toUpperCase());
+  return letters.join("");
+}
+
+function hasFrame(element: HTMLVideoElement | HTMLAudioElement): element is HTMLVideoElement {
+  return (
+    element instanceof HTMLVideoElement &&
+    element.readyState >= HTMLMediaElement.HAVE_CURRENT_DATA &&
+    element.videoWidth > 0 &&
+    element.videoHeight > 0
+  );
+}
+
+/** A camera fills its tile (cropped); a shared screen is shown whole (letterboxed). */
+function fit(video: HTMLVideoElement, rect: TileRect, cover: boolean): TileRect {
+  const scale = cover
+    ? Math.max(rect.width / video.videoWidth, rect.height / video.videoHeight)
+    : Math.min(rect.width / video.videoWidth, rect.height / video.videoHeight);
+  const width = video.videoWidth * scale;
+  const height = video.videoHeight * scale;
+  return {
+    x: rect.x + (rect.width - width) / 2,
+    y: rect.y + (rect.height - height) / 2,
+    width,
+    height,
+  };
+}
+
+/**
+ * Draws the recording's frames (decision D4): an equal grid of the room's video tiles on
+ * black, screen shares as one more tile, each with the participant's name. A participant
+ * without video shows their initials. Nothing here is a control; it is picture only.
+ */
+export function createFrameCompositor(
+  canvas: HTMLCanvasElement,
+  palette: CompositePalette,
+): FrameCompositor {
+  const context = canvas.getContext("2d", { alpha: false });
+  if (context === null) throw new Error("A 2D canvas context is not available");
+  const ctx = context;
+
+  function drawPlaceholder(tile: BoundMedia, rect: TileRect): void {
+    ctx.fillStyle = palette.tile;
+    ctx.fillRect(rect.x, rect.y, rect.width, rect.height);
+    ctx.fillStyle = palette.text;
+    ctx.font = `600 ${Math.round(rect.height / 4)}px ${palette.font}`;
+    ctx.textAlign = "center";
+    ctx.textBaseline = "middle";
+    ctx.fillText(initialsOf(tile.label), rect.x + rect.width / 2, rect.y + rect.height / 2);
+  }
+
+  function drawTag(label: string, rect: TileRect): void {
+    if (label === "") return;
+    ctx.font = `500 14px ${palette.font}`;
+    ctx.textAlign = "left";
+    ctx.textBaseline = "middle";
+    const width = Math.min(
+      rect.width - 2 * TAG_PADDING,
+      ctx.measureText(label).width + 2 * TAG_PADDING,
+    );
+    const x = rect.x + TAG_PADDING;
+    const y = rect.y + rect.height - TAG_HEIGHT - TAG_PADDING;
+    ctx.fillStyle = palette.tagBackground;
+    ctx.fillRect(x, y, width, TAG_HEIGHT);
+    ctx.fillStyle = palette.text;
+    ctx.fillText(label, x + TAG_PADDING, y + TAG_HEIGHT / 2, width - 2 * TAG_PADDING);
+  }
+
+  function drawTile(tile: BoundMedia, rect: TileRect): void {
+    ctx.save();
+    ctx.beginPath();
+    ctx.rect(rect.x, rect.y, rect.width, rect.height);
+    ctx.clip();
+    if (hasFrame(tile.element)) {
+      ctx.fillStyle = palette.background;
+      ctx.fillRect(rect.x, rect.y, rect.width, rect.height);
+      const target = fit(tile.element, rect, tile.kind === "camera");
+      ctx.drawImage(tile.element, target.x, target.y, target.width, target.height);
+    } else {
+      drawPlaceholder(tile, rect);
+    }
+    drawTag(tile.label, rect);
+    ctx.restore();
+  }
+
+  return {
+    draw: (tiles) => {
+      ctx.fillStyle = palette.background;
+      ctx.fillRect(0, 0, canvas.width, canvas.height);
+      const videoTiles = tiles.filter((tile) => tile.medium === "video");
+      const rects = computeGridLayout(videoTiles.length, canvas.width, canvas.height, GAP);
+      videoTiles.forEach((tile, index) => {
+        const rect = rects[index];
+        if (rect !== undefined) drawTile(tile, rect);
+      });
+    },
+  };
+}
diff --git a/apps/web/src/infrastructure/recording/frame-tick-worker.ts b/apps/web/src/infrastructure/recording/frame-tick-worker.ts
