new file mode 100644
index 00000000..1fbeb754
--- /dev/null
+++ b/apps/web/src/infrastructure/recording/local-microphone.ts
@@ -0,0 +1,87 @@
+// TJ-ARCH-MOB-001 compliant
+import type { RoomSnapshot } from "@know-meet/application";
+import type { AudioMixer } from "./audio-mixer";
+
+/** Opens the microphone the participant is using. Null when it cannot be opened. */
+export type CaptureMicrophone = (deviceId: string | null) => Promise<MediaStream | null>;
+
+/**
+ * The default capture: a second reading of the microphone the person already allowed. It
+ * needs no permission prompt because the room opened the same device. Echo cancelling
+ * stays on, so the recording holds this person's voice and not the room's.
+ */
+export const captureMicrophoneFromBrowser: CaptureMicrophone = async (deviceId) => {
+  if (typeof navigator.mediaDevices?.getUserMedia !== "function") return null;
+  try {
+    return await navigator.mediaDevices.getUserMedia({
+      audio:
+        deviceId === null
+          ? { echoCancellation: true, noiseSuppression: true }
+          : { deviceId: { exact: deviceId }, echoCancellation: true, noiseSuppression: true },
+      video: false,
+    });
+  } catch {
+    return null;
+  }
+};
+
+export interface LocalMicrophoneFeed {
+  /** Follows the snapshot: the chosen device, and silence while the participant is muted. */
+  sync(snapshot: RoomSnapshot): void;
+  dispose(): void;
+}
+
+export const LOCAL_MICROPHONE_KEY = "microphone:local";
+
+/**
+ * Feeds the participant's own voice into the mix. `attachMedia` never returns the local
+ * microphone (nobody should hear themselves), so it is captured here instead. Muting in the
+ * room sets this source's gain to zero; the capture stays open so unmuting is instant.
+ * Changing the room's microphone re-captures that device.
+ */
+export function createLocalMicrophoneFeed(
+  mixer: AudioMixer,
+  capture: CaptureMicrophone,
+): LocalMicrophoneFeed {
+  let stream: MediaStream | null = null;
+  let device: string | null | undefined;
+  let attempt = 0;
+  let muted = false;
+  let disposed = false;
+
+  const release = (): void => {
+    for (const track of stream?.getTracks() ?? []) track.stop();
+    stream = null;
+  };
+
+  const apply = (): void => mixer.setSource(LOCAL_MICROPHONE_KEY, stream, muted ? 0 : 1);
+
+  return {
+    sync: (snapshot) => {
+      muted = snapshot.local?.microphone.muted ?? true;
+      const wanted = snapshot.devices.active.microphone;
+      if (wanted === device) {
+        apply();
+        return;
+      }
+      device = wanted;
+      attempt += 1;
+      const mine = attempt;
+      void capture(wanted).then((next) => {
+        if (disposed || mine !== attempt) {
+          for (const track of next?.getTracks() ?? []) track.stop();
+          return;
+        }
+        release();
+        stream = next;
+        apply();
+      });
+    },
+    dispose: () => {
+      disposed = true;
+      attempt += 1;
+      release();
+      mixer.setSource(LOCAL_MICROPHONE_KEY, null, 0);
+    },
+  };
+}
diff --git a/apps/web/src/infrastructure/recording/media-bindings.ts b/apps/web/src/infrastructure/recording/media-bindings.ts
new file mode 100644
index 00000000..ff9dbb40
--- /dev/null
+++ b/apps/web/src/infrastructure/recording/media-bindings.ts
@@ -0,0 +1,97 @@
+// TJ-ARCH-MOB-001 compliant
+import type { RealtimeRoom, RoomSnapshot } from "@know-meet/application";
+import { type DesiredMedia, desiredMedia } from "./desired-media";
+
+/** One bound hidden media element and what it shows. */
+export interface BoundMedia {
+  readonly key: string;
+  readonly medium: "video" | "audio";
+  readonly kind: "camera" | "screen-share" | "audio";
+  readonly label: string;
+  readonly element: HTMLVideoElement | HTMLAudioElement;
+}
+
+export interface MediaBindings {
+  /** Binds new media and drops what the snapshot no longer has. */
+  sync(snapshot: RoomSnapshot): void;
+  /** Bound media in snapshot order: cameras and shares first as drawn, then audio. */
+  current(): readonly BoundMedia[];
+  /** Detaches everything and releases the elements. */
+  dispose(): void;
+}
+
+interface Entry {
+  readonly bound: BoundMedia;
+  readonly detach: () => void;
+}
+
+function createElement(medium: "video" | "audio"): HTMLVideoElement | HTMLAudioElement {
+  const element = document.createElement(medium);
+  // Muted: the meeting screen already plays the room; this element only feeds the recording.
+  element.muted = true;
+  element.autoplay = true;
+  if (element instanceof HTMLVideoElement) element.playsInline = true;
+  return element;
+}
+
+function kindOf(desired: DesiredMedia): BoundMedia["kind"] {
+  if (desired.medium === "audio") return "audio";
+  return desired.target.kind === "screen-share" ? "screen-share" : "camera";
+}
+
+/**
+ * Binds the room's media to hidden elements through `RealtimeRoom.attachMedia`, the same
+ * port the meeting screen uses. The room re-attaches a binding when a track is replaced or
+ * subscribed later, so an element keeps up without help from here. Elements are never added
+ * to the document.
+ */
+export function createMediaBindings(room: RealtimeRoom): MediaBindings {
+  const entries = new Map<string, Entry>();
+  let order: readonly string[] = [];
+
+  const drop = (key: string): void => {
+    const entry = entries.get(key);
+    if (entry === undefined) return;
+    entries.delete(key);
+    entry.detach();
+    entry.bound.element.srcObject = null;
+  };
+
+  return {
+    sync: (snapshot) => {
+      const wanted = desiredMedia(snapshot);
+      const keys = new Set(wanted.map((desired) => desired.key));
+      for (const key of [...entries.keys()]) if (!keys.has(key)) drop(key);
+      for (const desired of wanted) {
+        const existing = entries.get(desired.key);
+        if (existing !== undefined) {
+          if (existing.bound.label === desired.label) continue;
+          drop(desired.key);
+        }
+        const element = createElement(desired.medium);
+        const detach = room.attachMedia(desired.target, element);
+        void element.play().catch(() => undefined);
+        entries.set(desired.key, {
+          bound: {
+            key: desired.key,
+            medium: desired.medium,
+            kind: kindOf(desired),
+            label: desired.label,
+            element,
+          },
+          detach,
+        });
+      }
+      order = wanted.map((desired) => desired.key);
+    },
+    current: () =>
+      order.flatMap((key) => {
+        const entry = entries.get(key);
+        return entry === undefined ? [] : [entry.bound];
+      }),
+    dispose: () => {
+      for (const key of [...entries.keys()]) drop(key);
+      order = [];
+    },
+  };
+}
diff --git a/apps/web/src/infrastructure/recording/recording-constants.ts b/apps/web/src/infrastructure/recording/recording-constants.ts
new file mode 100644
index 00000000..491d9504
--- /dev/null
+++ b/apps/web/src/infrastructure/recording/recording-constants.ts
@@ -0,0 +1,31 @@
+// TJ-ARCH-MOB-001 compliant
+
+/** The OPFS directory that holds every recording file. One per origin. */
+export const RECORDINGS_DIRECTORY = "know-meet-recordings";
+
+/** Web Lock name prefix. A recording's writer holds `${prefix}${id}` for as long as it writes. */
+export const RECORDING_LOCK_PREFIX = "know-meet-recording:";
+
+/** BroadcastChannel that tells other tabs which recording changed (ids only). */
+export const RECORDING_CHANNEL_NAME = "know-meet-recording-changes";
+
+/** `MediaRecorder` hands over a chunk this often, so little is lost if the tab dies. */
+export const RECORDER_TIMESLICE_MS = 1000;
+
+/** Composite canvas size and frame rate. 720p keeps a one-hour grid near 1 GB. */
+export const COMPOSITE_WIDTH = 1280;
+export const COMPOSITE_HEIGHT = 720;
+export const COMPOSITE_FPS = 25;
+export const VIDEO_BITS_PER_SECOND = 2_500_000;
+export const AUDIO_BITS_PER_SECOND = 96_000;
+
+/**
+ * A recording does not start with less free space than this (about three minutes at the
+ * bit rate above). The estimate is advisory; a write that still fails stops the
+ * recording and keeps what was written.
+ */
+export const MIN_FREE_BYTES = 64 * 1024 * 1024;
+
+export function recordingLockName(id: string): string {
+  return `${RECORDING_LOCK_PREFIX}${id}`;
+}
diff --git a/apps/web/src/infrastructure/recording/recording-library.ts b/apps/web/src/infrastructure/recording/recording-library.ts
new file mode 100644
index 00000000..1d578535
--- /dev/null
+++ b/apps/web/src/infrastructure/recording/recording-library.ts
@@ -0,0 +1,217 @@
+// TJ-ARCH-MOB-001 compliant
+import {
+  err,
+  ok,
+  parseRecordingRequestId,
+  type RecordingRequestId,
+  type Result,
+  type Support,
+} from "@know-meet/domain";
+import type {
+  LocalRecording,
+  PlaybackSource,
+  RecordingLibrary,
+  RecordingLibraryError,
+  RecordingState,
+  RecordingStorageInfo,
+} from "./library-types";
+import { extensionFor, hasRecordingStorage } from "./recording-support";
+import type { RecordingChangeBus } from "./store/recording-change-bus";
+import {
+  estimateStorage,
+  heldRecordingIds,
+  listRecordingFiles,
+  openRecordingFile,
+  type RecordingFileInfo,
+  removeRecordingFile,
+} from "./store/recording-files";
+import type {
+  IndexedRecording,
+  RecordingIndex,
+  RecordingMeetingLink,
+} from "./store/recording-index";
+
+export interface RecordingLibraryOptions {
+  readonly index: RecordingIndex;
+  readonly changes: RecordingChangeBus;
+  /** The id this tab is recording right now, or null. */
+  readonly localActiveId: () => RecordingRequestId | null;
+  readonly isPersisted: () => Promise<boolean>;
+  readonly requestPersistence: () => Promise<boolean>;
+}
+
+const unavailable = (): RecordingLibraryError => ({ code: "recordings-unavailable" });
+const failed = (): RecordingLibraryError => ({ code: "recordings-failed" });
+
+/** The state of a row, from what the index says, what the file system has and who holds the lock. */
+function stateOf(
+  row: IndexedRecording | null,
+  file: RecordingFileInfo | undefined,
+  writing: boolean,
+): RecordingState {
+  if (writing) return "recording";
+  if (file === undefined) return "missing";
+  if (row === null || row.endReason === null || row.endReason === "failed") return "incomplete";
+  return row.endReason === "storage-full" ? "stopped-early" : "complete";
+}
+
+function describeRow(
+  row: IndexedRecording,
+  file: RecordingFileInfo | undefined,
+  link: RecordingMeetingLink | undefined,
+  writing: boolean,
+  here: boolean,
+): LocalRecording {
+  return {
+    id: row.id,
+    roomCode: row.roomCode ?? link?.roomCode ?? null,
+    meetingId: link?.meetingId ?? null,
+    meetingTitle: link?.title ?? null,
+    startedAt: row.startedAt,
+    endedAt: row.endedAt,
+    mimeType: row.mimeType,
+    sizeBytes: file?.size ?? row.sizeBytes,
+    state: stateOf(row, file, writing),
+    recordingHere: here,
+  };
+}
+
+/** A file with no index row (the index was unavailable, or the row was lost). */
+function describeOrphan(
+  id: RecordingRequestId,
+  file: RecordingFileInfo,
+  link: RecordingMeetingLink | undefined,
+  writing: boolean,
+  here: boolean,
+): LocalRecording {
+  return {
+    id,
+    roomCode: link?.roomCode ?? null,
+    meetingId: link?.meetingId ?? null,
+    meetingTitle: link?.title ?? null,
+    startedAt: file.lastModified ?? 0,
+    endedAt: null,
+    mimeType: file.name.endsWith(".mp4") ? "video/mp4" : "video/webm",
+    sizeBytes: file.size ?? 0,
+    state: stateOf(null, file, writing),
+    recordingHere: here,
+  };
+}
+
+/** The id a file name carries, or null for a file that is not a recording of ours. */
+function idOfFile(name: string): RecordingRequestId | null {
+  const dot = name.lastIndexOf(".");
+  return dot <= 0 ? null : parseRecordingRequestId(name.slice(0, dot));
+}
+
+/**
+ * The recordings library (wc10, WC-10): the index rows joined with what OPFS actually
+ * holds and which writers are alive. The file system is the truth for size and presence;
+ * the index adds the meeting, times and how it ended; a Web Lock tells a recording that
+ * is still being written from one whose tab died.
+ */
+export function createRecordingLibrary(options: RecordingLibraryOptions): RecordingLibrary {
+  const support: Support = hasRecordingStorage() ? "supported" : "unsupported";
+
+  const readAll = async (
+    signal?: AbortSignal,
+  ): Promise<Result<readonly LocalRecording[], RecordingLibraryError>> => {
+    signal?.throwIfAborted();
+    const files = await listRecordingFiles();
+    if (files === null) return err(unavailable());
+    const [rows, links, held] = await Promise.all([
+      options.index.rows(),
+      options.index.links(),
+      heldRecordingIds(),
+    ]);
+    signal?.throwIfAborted();
+    const active = options.localActiveId();
+    // Without the Web Locks API only this tab's own recording is known to be running.
+    const isWriting = (id: string): boolean => (held === null ? active === id : held.has(id));
+    const entries: LocalRecording[] = [];
+    const seen = new Set<string>();
+    for (const row of rows ?? []) {
+      seen.add(row.fileName);
+      const link = links.get(row.id);
+      entries.push(
+        describeRow(row, files.get(row.fileName), link, isWriting(row.id), active === row.id),
+      );
+    }
+    for (const [name, file] of files) {
+      if (seen.has(name)) continue;
+      const id = idOfFile(name);
+      if (id === null) continue;
+      entries.push(describeOrphan(id, file, links.get(id), isWriting(id), active === id));
+    }
+    entries.sort((a, b) => b.startedAt - a.startedAt || (a.id < b.id ? 1 : -1));
+    return ok(entries);
+  };
+
+  const findOne = async (
+    id: RecordingRequestId,
+  ): Promise<Result<LocalRecording | null, RecordingLibraryError>> => {
+    try {
+      const all = await readAll();
+      return all.ok ? ok(all.value.find((entry) => entry.id === id) ?? null) : all;
+    } catch {
+      return err(failed());
+    }
+  };
+
+  const storage = async (): Promise<RecordingStorageInfo> => ({
+    support,
+    ...(await estimateStorage()),
+    persisted: await options.isPersisted(),
+  });
+
+  return {
+    support,
+    list: async (signal) => {
+      try {
+        return await readAll(signal);
+      } catch {
+        if (signal?.aborted === true) throw signal.reason;
+        return err(failed());
+      }
+    },
+    get: findOne,
+    openPlayback: async (id) => {
+      const found = await findOne(id);
+      if (!found.ok) return found;
+      const entry = found.value;
+      if (entry === null || entry.state === "missing")
+        return err({ code: "recording-file-missing" });
+      if (entry.state === "recording") return err({ code: "recording-in-progress" });
+      const file = await openRecordingFile(`${id}.${extensionFor(entry.mimeType)}`);
+      if (file === null) return err({ code: "recording-file-missing" });
+      // A typed view of the same bytes: the blob is a lazy slice, nothing is copied.
+      const url = URL.createObjectURL(file.slice(0, file.size, entry.mimeType));
+      const source: PlaybackSource = {
+        url,
+        mimeType: entry.mimeType,
+        revoke: () => URL.revokeObjectURL(url),
+      };
+      return ok(source);
+    },
+    remove: async (id) => {
+      const found = await findOne(id);
+      if (!found.ok) return found;
+      const entry = found.value;
+      if (entry?.state === "recording") return err({ code: "recording-in-progress" });
+      const outcome = await removeRecordingFile(
+        `${id}.${extensionFor(entry?.mimeType ?? "video/webm")}`,
+      );
+      if (outcome === "busy") return err({ code: "recording-in-progress" });
+      if (outcome === "failed") return err(failed());
+      if (!(await options.index.remove(id))) return err(failed());
+      options.changes.publish({ kind: "deleted", id });
+      return ok(undefined);
+    },
+    storage,
+    requestPersistence: async () => {
+      await options.requestPersistence();
+      return storage();
+    },
+    subscribe: (listener) => options.changes.subscribe(listener),
+  };
+}
diff --git a/apps/web/src/infrastructure/recording/recording-support.ts b/apps/web/src/infrastructure/recording/recording-support.ts
new file mode 100644
index 00000000..53c28b2e
--- /dev/null
+++ b/apps/web/src/infrastructure/recording/recording-support.ts
@@ -0,0 +1,64 @@
+// TJ-ARCH-MOB-001 compliant
+import type { Support } from "@know-meet/domain";
+
+/**
+ * Candidates in order of preference. VP9 and VP8 give WebM in Chromium and Firefox; MP4 is
+ * the only container Safari's `MediaRecorder` offers.
+ */
+const MIME_CANDIDATES: readonly string[] = [
+  "video/webm;codecs=vp9,opus",
+  "video/webm;codecs=vp8,opus",
+  "video/webm",
+  "video/mp4;codecs=avc1,mp4a.40.2",
+  "video/mp4",
+];
+
+export interface ChosenFormat {
+  readonly mimeType: string;
+  /** File extension without the dot. */
+  readonly extension: "webm" | "mp4";
+}
+
+/** The first candidate the browser can record, or null when it can record none. */
+export function pickRecordingFormat(
+  isTypeSupported: (type: string) => boolean = (type) => MediaRecorder.isTypeSupported(type),
+): ChosenFormat | null {
+  for (const mimeType of MIME_CANDIDATES) {
+    if (isTypeSupported(mimeType)) {
+      return { mimeType, extension: mimeType.startsWith("video/mp4") ? "mp4" : "webm" };
+    }
+  }
+  return null;
+}
+
+/** File extension for a stored recording's mime type. */
+export function extensionFor(mimeType: string): "webm" | "mp4" {
+  return mimeType.startsWith("video/mp4") ? "mp4" : "webm";
+}
+
+/** True when this browser has the file system the recordings are written to. */
+export function hasRecordingStorage(): boolean {
+  return (
+    typeof navigator !== "undefined" &&
+    typeof navigator.storage !== "undefined" &&
+    typeof navigator.storage.getDirectory === "function" &&
+    typeof Worker !== "undefined"
+  );
+}
+
+/**
+ * Whether this browser can record locally at all: `MediaRecorder`, canvas `captureStream`,
+ * `AudioContext`, OPFS and workers, and at least one container it can write.
+ */
+export function detectRecordingSupport(): Support {
+  if (
+    typeof MediaRecorder === "undefined" ||
+    typeof AudioContext === "undefined" ||
+    typeof HTMLCanvasElement === "undefined" ||
+    typeof HTMLCanvasElement.prototype.captureStream !== "function" ||
+    !hasRecordingStorage()
+  ) {
+    return "unsupported";
+  }
+  return pickRecordingFormat() === null ? "unsupported" : "supported";
+}
diff --git a/apps/web/src/infrastructure/recording/store/opfs-types.ts b/apps/web/src/infrastructure/recording/store/opfs-types.ts
new file mode 100644
index 00000000..7ac4cce4
--- /dev/null
+++ b/apps/web/src/infrastructure/recording/store/opfs-types.ts
@@ -0,0 +1,47 @@
+// TJ-ARCH-MOB-001 compliant
+
+/**
+ * The slices of the Origin Private File System the recording code uses, typed here so the
+ * code does not depend on which of them the installed DOM library declares (the
+ * synchronous access handle exists only in workers, and async iteration is a separate
+ * library file).
+ */
+export interface FileHandleLike {
+  readonly kind: "file";
+  getFile(): Promise<File>;
+  createSyncAccessHandle(): Promise<SyncAccessHandleLike>;
+}
+
+export interface SyncAccessHandleLike {
+  /** Writes at `options.at`; returns the bytes written, which can be fewer than asked. */
+  write(buffer: ArrayBuffer | ArrayBufferView, options?: { at?: number }): number;
+  getSize(): number;
+  flush(): void;
+  close(): void;
+}
+
+export interface DirectoryHandleLike {
+  readonly kind: "directory";
+  entries(): AsyncIterable<[string, DirectoryHandleLike | FileHandleLike]>;
+  getFileHandle(name: string, options?: { create?: boolean }): Promise<FileHandleLike>;
+  getDirectoryHandle(name: string, options?: { create?: boolean }): Promise<DirectoryHandleLike>;
+  removeEntry(name: string): Promise<void>;
+}
+
+/** The OPFS root; throws where the browser has no OPFS or refuses it (some private modes). */
+export async function opfsRoot(): Promise<DirectoryHandleLike> {
+  return (await navigator.storage.getDirectory()) as unknown as DirectoryHandleLike;
+}
+
+/** The recordings directory. With `create: false` it throws if nothing was ever recorded. */
+export async function recordingsDirectory(
+  directoryName: string,
+  create: boolean,
+): Promise<DirectoryHandleLike> {
+  return (await opfsRoot()).getDirectoryHandle(directoryName, { create });
+}
+
+/** True for a thrown `DOMException` with the given name. */
+export function isDomError(error: unknown, name: string): boolean {
+  return typeof error === "object" && error !== null && "name" in error && error.name === name;
+}
diff --git a/apps/web/src/infrastructure/recording/store/recording-change-bus.ts b/apps/web/src/infrastructure/recording/store/recording-change-bus.ts
new file mode 100644
index 00000000..fcde9581
--- /dev/null
+++ b/apps/web/src/infrastructure/recording/store/recording-change-bus.ts
@@ -0,0 +1,83 @@
+// TJ-ARCH-MOB-001 compliant
+import { parseRecordingRequestId } from "@know-meet/domain";
+import type { RecordingChange } from "../library-types";
+import { RECORDING_CHANNEL_NAME } from "../recording-constants";
+
+export interface RecordingChangeBus {
+  /** Tells this tab's listeners and other tabs. Never throws. */
+  publish(change: RecordingChange): void;
+  subscribe(listener: (change: RecordingChange) => void): () => void;
+}
+
+interface ChannelLike {
+  onmessage: ((event: MessageEvent<unknown>) => void) | null;
+  postMessage(message: unknown): void;
+}
+
+/** A change from another tab is outside data: rebuild it with the domain brand or drop it. */
+export function parseRecordingChange(value: unknown): RecordingChange | null {
+  if (typeof value !== "object" || value === null) return null;
+  const record = value as Record<string, unknown>;
+  const id = parseRecordingRequestId(record["id"]);
+  if (id === null) return null;
+  if (record["kind"] === "changed") return { kind: "changed", id };
+  if (record["kind"] === "deleted") return { kind: "deleted", id };
+  return null;
+}
+
+function openBroadcastChannel(): ChannelLike | null {
+  if (typeof BroadcastChannel === "undefined") return null;
+  try {
+    return new BroadcastChannel(RECORDING_CHANNEL_NAME);
+  } catch {
+    return null;
+  }
+}
+
+/** Same shape as the history change bus; the channel opens on first use. */
+export function createRecordingChangeBus(
+  openChannel: () => ChannelLike | null = openBroadcastChannel,
+): RecordingChangeBus {
+  const listeners = new Set<(change: RecordingChange) => void>();
+  let channel: ChannelLike | null | undefined;
+
+  const notify = (change: RecordingChange): void => {
+    for (const listener of [...listeners]) {
+      try {
+        listener(change);
+      } catch {
+        // One failing listener must not stop the others or the write that caused this.
+      }
+    }
+  };
+
+  const ensureChannel = (): ChannelLike | null => {
+    if (channel !== undefined) return channel;
+    channel = openChannel();
+    if (channel !== null) {
+      channel.onmessage = (event) => {
+        const change = parseRecordingChange(event.data);
+        if (change !== null) notify(change);
+      };
+    }
+    return channel;
+  };
+
+  return {
+    publish: (change) => {
+      notify(change);
+      try {
+        ensureChannel()?.postMessage(change);
+      } catch {
+        // Another tab missing one notice only delays its refresh until its next read.
+      }
+    },
+    subscribe: (listener) => {
+      listeners.add(listener);
+      ensureChannel();
+      return () => {
+        listeners.delete(listener);
+      };
+    },
+  };
+}
diff --git a/apps/web/src/infrastructure/recording/store/recording-files.ts b/apps/web/src/infrastructure/recording/store/recording-files.ts
new file mode 100644
index 00000000..d5d43eaf
--- /dev/null
+++ b/apps/web/src/infrastructure/recording/store/recording-files.ts
@@ -0,0 +1,107 @@
+// TJ-ARCH-MOB-001 compliant
+import { RECORDING_LOCK_PREFIX, RECORDINGS_DIRECTORY } from "../recording-constants";
+import {
+  type DirectoryHandleLike,
+  type FileHandleLike,
+  isDomError,
+  recordingsDirectory,
+} from "./opfs-types";
+
+/** What a recording file looks like on disk. `size` is null when the file cannot be read now. */
+export interface RecordingFileInfo {
+  readonly name: string;
+  readonly size: number | null;
+  readonly lastModified: number | null;
+}
+
+/**
+ * Every file in the recordings directory, by name. Null when this browser has no OPFS or
+ * refuses it; an empty map when nothing was ever recorded.
+ */
+export async function listRecordingFiles(): Promise<ReadonlyMap<string, RecordingFileInfo> | null> {
+  let directory: DirectoryHandleLike;
+  try {
+    directory = await recordingsDirectory(RECORDINGS_DIRECTORY, false);
+  } catch (error) {
+    return isDomError(error, "NotFoundError") ? new Map() : null;
+  }
+  const files = new Map<string, RecordingFileInfo>();
+  try {
+    for await (const [name, handle] of directory.entries()) {
+      if (handle.kind !== "file") continue;
+      files.set(name, await describeFile(name, handle));
+    }
+  } catch {
+    return null;
+  }
+  return files;
+}
+
+async function describeFile(name: string, handle: FileHandleLike): Promise<RecordingFileInfo> {
+  try {
+    const file = await handle.getFile();
+    return { name, size: file.size, lastModified: file.lastModified };
+  } catch {
+    // A file another tab is writing can refuse to be read for a moment.
+    return { name, size: null, lastModified: null };
+  }
+}
+
+/** The file itself, or null when it is not there or cannot be read now. */
+export async function openRecordingFile(name: string): Promise<File | null> {
+  try {
+    const directory = await recordingsDirectory(RECORDINGS_DIRECTORY, false);
+    return await (await directory.getFileHandle(name)).getFile();
+  } catch {
+    return null;
+  }
+}
+
+export type RemoveFileOutcome = "removed" | "missing" | "busy" | "failed";
+
+/** Deletes one recording file. `busy` when a writer still holds it open. */
+export async function removeRecordingFile(name: string): Promise<RemoveFileOutcome> {
+  try {
+    const directory = await recordingsDirectory(RECORDINGS_DIRECTORY, false);
+    await directory.removeEntry(name);
+    return "removed";
+  } catch (error) {
+    if (isDomError(error, "NotFoundError")) return "missing";
+    if (isDomError(error, "NoModificationAllowedError") || isDomError(error, "InvalidStateError")) {
+      return "busy";
+    }
+    return "failed";
+  }
+}
+
+/**
+ * Recording ids whose writer holds the lock right now, in this tab or another. Null where
+ * the Web Locks API is missing, so the caller cannot tell.
+ */
+export async function heldRecordingIds(): Promise<ReadonlySet<string> | null> {
+  if (typeof navigator === "undefined" || typeof navigator.locks?.query !== "function") return null;
+  try {
+    const state = await navigator.locks.query();
+    const ids = new Set<string>();
+    for (const lock of state.held ?? []) {
+      const name = lock.name ?? "";
+      if (name.startsWith(RECORDING_LOCK_PREFIX)) ids.add(name.slice(RECORDING_LOCK_PREFIX.length));
+    }
+    return ids;
+  } catch {
+    return null;
+  }
+}
+
+/** The browser's storage estimate; nulls where it will not say. */
+export async function estimateStorage(): Promise<{
+  readonly usedBytes: number | null;
+  readonly quotaBytes: number | null;
+}> {
+  try {
+    const estimate = await navigator.storage.estimate();
+    return { usedBytes: estimate.usage ?? null, quotaBytes: estimate.quota ?? null };
+  } catch {
+    return { usedBytes: null, quotaBytes: null };
+  }
+}
diff --git a/apps/web/src/infrastructure/recording/store/recording-index.ts b/apps/web/src/infrastructure/recording/store/recording-index.ts
new file mode 100644
index 00000000..3298a049
--- /dev/null
+++ b/apps/web/src/infrastructure/recording/store/recording-index.ts
@@ -0,0 +1,189 @@
+// TJ-ARCH-MOB-001 compliant
+import { parseRecordingRequestId, type RecordingRequestId } from "@know-meet/domain";
+import type { HistoryDatabase } from "../../history/history-database";
+import { migrateHistory } from "../../history/history-schema";
+import type { RecordingIndexWriter } from "../library-types";
+import type { RecordingChangeBus } from "./recording-change-bus";
+
+/** One row of the `recording` table, as the library reads it. */
+export interface IndexedRecording {
+  readonly id: RecordingRequestId;
+  readonly roomCode: string | null;
+  readonly fileName: string;
+  readonly mimeType: string;
+  readonly startedAt: number;
+  readonly endedAt: number | null;
+  readonly sizeBytes: number;
+  readonly endReason: "stopped" | "storage-full" | "failed" | null;
+}
+
+/** The history session a recording is linked to. */
+export interface RecordingMeetingLink {
+  readonly meetingId: string;
+  readonly title: string | null;
+  readonly roomCode: string;
+}
+
+export interface RecordingIndex extends RecordingIndexWriter {
+  /** Null when the browser cannot keep the index (no IndexedDB, private window). */
+  rows(): Promise<readonly IndexedRecording[] | null>;
+  links(): Promise<ReadonlyMap<string, RecordingMeetingLink>>;
+  remove(id: RecordingRequestId): Promise<boolean>;
+}
+
+interface IndexRow {
+  readonly id: string;
+  readonly room_code: string | null;
+  readonly file_name: string;
+  readonly mime_type: string;
+  readonly started_at: unknown;
+  readonly ended_at: unknown;
+  readonly size_bytes: unknown;
+  readonly end_reason: string | null;
+}
+
+interface LinkRow {
+  readonly recording_id: string;
+  readonly meeting_id: string;
+  readonly title: string | null;
+  readonly room_code: string;
+}
+
+/** bigint columns arrive as numbers or strings depending on the driver path. */
+function toNumber(value: unknown): number | null {
+  const number = Number(value);
+  return Number.isFinite(number) ? number : null;
+}
+
+function toEndReason(value: string | null): IndexedRecording["endReason"] {
+  return value === "stopped" || value === "storage-full" || value === "failed" ? value : null;
+}
+
+function toIndexed(row: IndexRow): IndexedRecording | null {
+  const id = parseRecordingRequestId(row.id);
+  const startedAt = toNumber(row.started_at);
+  if (id === null || startedAt === null) return null;
+  return {
+    id,
+    roomCode: row.room_code,
+    fileName: row.file_name,
+    mimeType: row.mime_type,
+    startedAt,
+    endedAt: row.ended_at === null ? null : toNumber(row.ended_at),
+    sizeBytes: toNumber(row.size_bytes) ?? 0,
+    endReason: toEndReason(row.end_reason),
+  };
+}
+
+export interface RecordingIndexOptions {
+  /** The shared history database (the same worker group as history). */
+  readonly openDatabase: () => Promise<HistoryDatabase>;
+  readonly changes: RecordingChangeBus;
+}
+
+/**
+ * The recording index over the history database (wc10 task 10.2). It lives there, not in
+ * OPFS metadata, because the history store is already shared by every tab through one
+ * leader worker, is transactional, and already holds the link from a meeting to its
+ * recordings, so one query lists a recording with its meeting. Nothing depends on it for
+ * the recording itself: if the index cannot be opened, the recorder still writes the file
+ * and the library finds it by listing OPFS.
+ */
+export function createRecordingIndex(options: RecordingIndexOptions): RecordingIndex {
+  let opening: Promise<HistoryDatabase | null> | null = null;
+
+  /** Null when the database cannot open. A failed open is tried again next time. */
+  const database = (): Promise<HistoryDatabase | null> => {
+    if (opening === null) {
+      const attempt = options
+        .openDatabase()
+        .then(async (db) => {
+          await migrateHistory(db);
+          return db;
+        })
+        .catch((): null => null);
+      opening = attempt;
+      void attempt.then((db) => {
+        if (db === null && opening === attempt) opening = null;
+      });
+    }
+    return opening;
+  };
+
+  return {
+    begin: async (entry) => {
+      try {
+        const db = await database();
+        if (db === null) return;
+        await db.query(
+          `INSERT INTO recording (id, room_code, file_name, mime_type, started_at)
+           VALUES ($1, $2, $3, $4, $5)
+           ON CONFLICT (id) DO NOTHING`,
+          [entry.id, entry.roomCode, entry.fileName, entry.mimeType, entry.startedAt],
+        );
+        options.changes.publish({ kind: "changed", id: entry.id });
+      } catch {
+        // The file is still written; the library finds it by listing the directory.
+      }
+    },
+    finish: async (entry) => {
+      try {
+        const db = await database();
+        if (db === null) return;
+        await db.query(
+          `UPDATE recording SET ended_at = $2, size_bytes = $3, end_reason = $4 WHERE id = $1`,
+          [entry.id, entry.endedAt, entry.sizeBytes, entry.endReason],
+        );
+        options.changes.publish({ kind: "changed", id: entry.id });
+      } catch {
+        // The row stays open: the library lists it as incomplete, with the file's real size.
+      }
+    },
+    rows: async () => {
+      try {
+        const db = await database();
+        if (db === null) return null;
+        const result = await db.query<IndexRow>(
+          "SELECT * FROM recording ORDER BY started_at DESC, id DESC",
+        );
+        return result.rows.map(toIndexed).filter((row) => row !== null);
+      } catch {
+        return null;
+      }
+    },
+    links: async () => {
+      const links = new Map<string, RecordingMeetingLink>();
+      try {
+        const db = await database();
+        if (db === null) return links;
+        const result = await db.query<LinkRow>(
+          `SELECT DISTINCT ON (l.recording_id)
+                  l.recording_id, l.meeting_id, s.title, s.room_code
+             FROM meeting_recording_link l
+             JOIN meeting_session s ON s.id = l.meeting_id
+            ORDER BY l.recording_id, l.linked_at`,
+        );
+        for (const row of result.rows) {
+          links.set(row.recording_id, {
+            meetingId: row.meeting_id,
+            title: row.title,
+            roomCode: row.room_code,
+          });
+        }
+      } catch {
+        // Without links a recording lists without its meeting; it is still listed.
+      }
+      return links;
+    },
+    remove: async (id) => {
+      try {
+        const db = await database();
+        if (db === null) return true;
+        await db.query("DELETE FROM recording WHERE id = $1", [id]);
+        return true;
+      } catch {
+        return false;
+      }
+    },
+  };
+}
diff --git a/apps/web/src/infrastructure/recording/writer/opfs-writer-client.ts b/apps/web/src/infrastructure/recording/writer/opfs-writer-client.ts
new file mode 100644
index 00000000..bfb321b0
--- /dev/null
+++ b/apps/web/src/infrastructure/recording/writer/opfs-writer-client.ts
@@ -0,0 +1,131 @@
+// TJ-ARCH-MOB-001 compliant
+import { conferencingErrors, err, ok, type RecorderFailed, type Result } from "@know-meet/domain";
+import type { WriterEvent, WriterFailure, WriterRequest } from "./writer-protocol";
+
+/**
+ * Appends a recording to one OPFS file through the writer worker. Nothing here reaches a
+ * network: the file lives in the origin's private file system.
+ */
+export interface RecordingWriter {
+  /** Opens (creating) the file and takes the recording lock. Call once. */
+  open(fileName: string, lockName: string): Promise<Result<void, RecorderFailed>>;
+  /** Queues a chunk, in order. Hands the buffer to the worker; do not use it afterwards. */
+  append(chunk: ArrayBuffer): void;
+  /** Flushes and closes. Resolves with the bytes written; never rejects, never hangs. */
+  close(): Promise<number>;
+  /** Called once if the worker stops writing by itself; the file is already closed. */
+  onFailed(listener: (reason: WriterFailure, size: number) => void): () => void;
+}
+
+const CLOSE_TIMEOUT_MS = 10_000;
+
+function recorderFailure(reason: WriterFailure): RecorderFailed {
+  return conferencingErrors.recorderFailed(
+    reason === "quota-exceeded"
+      ? "quota-exceeded"
+      : reason === "storage-unavailable"
+        ? "storage-unavailable"
+        : "failed",
+  );
+}
+
+export function createOpfsWriter(): RecordingWriter {
+  let worker: Worker | null = null;
+  let settleOpen: ((result: Result<void, RecorderFailed>) => void) | null = null;
+  let settleClose: ((size: number) => void) | null = null;
+  let finalSize = 0;
+  let ended = false;
+  const failedListeners = new Set<(reason: WriterFailure, size: number) => void>();
+
+  const send = (request: WriterRequest, transfer: Transferable[] = []): void => {
+    worker?.postMessage(request, transfer);
+  };
+
+  const stopWorker = (): void => {
+    worker?.terminate();
+    worker = null;
+  };
+
+  const onEvent = (event: WriterEvent): void => {
+    switch (event.type) {
+      case "opened":
+        settleOpen?.(ok(undefined));
+        settleOpen = null;
+        return;
+      case "closed":
+        ended = true;
+        finalSize = event.size;
+        settleClose?.(event.size);
+        settleClose = null;
+        stopWorker();
+        return;
+      case "failed":
+        ended = true;
+        finalSize = event.size;
+        if (settleOpen !== null) {
+          settleOpen(err(recorderFailure(event.reason)));
+          settleOpen = null;
+        } else {
+          for (const listener of [...failedListeners]) listener(event.reason, event.size);
+        }
+        settleClose?.(event.size);
+        settleClose = null;
+        stopWorker();
+        return;
+    }
+  };
+
+  const onWorkerCrash = (): void => onEvent({ type: "failed", reason: "failed", size: finalSize });
+
+  return {
+    open: (fileName, lockName) => {
+      if (typeof Worker === "undefined") {
+        return Promise.resolve(err(conferencingErrors.recorderFailed("storage-unavailable")));
+      }
+      return new Promise((resolve) => {
+        try {
+          worker = new Worker(new URL("./opfs-writer-worker.ts", import.meta.url), {
+            type: "module",
+            name: "know-meet-recording-writer",
+          });
+        } catch {
+          resolve(err(conferencingErrors.recorderFailed("storage-unavailable")));
+          return;
+        }
+        settleOpen = resolve;
+        worker.addEventListener("message", (event: MessageEvent<WriterEvent>) =>
+          onEvent(event.data),
+        );
+        worker.addEventListener("error", onWorkerCrash);
+        worker.addEventListener("messageerror", onWorkerCrash);
+        send({ type: "open", fileName, lockName });
+      });
+    },
+    append: (chunk) => {
+      if (ended) return;
+      send({ type: "append", chunk }, [chunk]);
+    },
+    close: () => {
+      if (ended || worker === null) return Promise.resolve(finalSize);
+      return new Promise<number>((resolve) => {
+        const timer = setTimeout(() => {
+          settleClose = null;
+          ended = true;
+          stopWorker();
+          resolve(finalSize);
+        }, CLOSE_TIMEOUT_MS);
+        settleClose = (size) => {
+          clearTimeout(timer);
+          resolve(size);
+        };
+        send({ type: "close" });
+      });
+    },
+    onFailed: (listener) => {
+      failedListeners.add(listener);
+      return () => {
+        failedListeners.delete(listener);
+      };
+    },
+  };
+}
diff --git a/apps/web/src/infrastructure/recording/writer/opfs-writer-worker.ts b/apps/web/src/infrastructure/recording/writer/opfs-writer-worker.ts
new file mode 100644
index 00000000..1d1870bf
--- /dev/null
+++ b/apps/web/src/infrastructure/recording/writer/opfs-writer-worker.ts
@@ -0,0 +1,154 @@
+// TJ-ARCH-MOB-001 compliant
+
+import { RECORDINGS_DIRECTORY } from "../recording-constants";
+import {
+  type DirectoryHandleLike,
+  isDomError,
+  recordingsDirectory,
+  type SyncAccessHandleLike,
+} from "../store/opfs-types";
+import type { WriterEvent, WriterFailure, WriterRequest } from "./writer-protocol";
+
+/**
+ * The recording writer (wc10 task 10.2). A dedicated worker owns one OPFS file through a
+ * synchronous access handle, which only workers may open and which writes without blocking
+ * the page. Chunks are appended in the order they arrive and flushed each time, so a tab
+ * that dies mid-recording leaves a file that holds everything up to the last chunk.
+ *
+ * It also holds a Web Lock named after the recording for as long as it writes. Another
+ * tab reads that lock to tell "still recording" from "never finished". The lock is
+ * released when the worker closes the file, fails, or dies with the tab.
+ */
+interface WorkerScope {
+  postMessage(message: WriterEvent): void;
+  addEventListener(type: "message", listener: (event: MessageEvent<WriterRequest>) => void): void;
+}
+
+const scope = self as unknown as WorkerScope;
+
+let handle: SyncAccessHandleLike | null = null;
+let offset = 0;
+let releaseLock: (() => void) | null = null;
+let finished = false;
+
+function post(event: WriterEvent): void {
+  scope.postMessage(event);
+}
+
+/** Resolves once the lock is held; it stays held until `releaseLock` runs. */
+function holdLock(name: string): Promise<void> {
+  if (typeof navigator.locks === "undefined") return Promise.resolve();
+  return new Promise<void>((acquired, rejected) => {
+    navigator.locks
+      .request(name, { mode: "exclusive" }, () => {
+        return new Promise<void>((release) => {
+          releaseLock = release;
+          acquired();
+        });
+      })
+      .catch(rejected);
+  });
+}
+
+function release(): void {
+  const done = releaseLock;
+  releaseLock = null;
+  done?.();
+}
+
+/** Flushes and closes the file, keeping what was written. Never throws. */
+function closeFile(): number {
+  const open = handle;
+  handle = null;
+  if (open !== null) {
+    try {
+      open.flush();
+    } catch {
+      // The bytes already written stay; a failed flush cannot make them worse.
+    }
+    try {
+      open.close();
+    } catch {
+      // Closing a handle that already failed has nothing left to release.
+    }
+  }
+  release();
+  return offset;
+}
+
+function failureOf(error: unknown): WriterFailure {
+  return isDomError(error, "QuotaExceededError") ? "quota-exceeded" : "failed";
+}
+
+function fail(reason: WriterFailure): void {
+  finished = true;
+  post({ type: "failed", reason, size: closeFile() });
+}
+
+async function open(request: Extract<WriterRequest, { type: "open" }>): Promise<void> {
+  try {
+    await holdLock(request.lockName);
+  } catch {
+    fail("storage-unavailable");
+    return;
+  }
+  let directory: DirectoryHandleLike;
+  try {
+    directory = await recordingsDirectory(RECORDINGS_DIRECTORY, true);
+    const file = await directory.getFileHandle(request.fileName, { create: true });
+    handle = await file.createSyncAccessHandle();
+    offset = handle.getSize();
+  } catch {
+    fail("storage-unavailable");
+    return;
+  }
+  post({ type: "opened" });
+}
+
+function append(chunk: ArrayBuffer): void {
+  const open = handle;
+  if (open === null) return;
+  const bytes = new Uint8Array(chunk);
+  let written = 0;
+  try {
+    while (written < bytes.byteLength) {
+      const count = open.write(bytes.subarray(written), { at: offset });
+      // A write that accepts nothing is how a full disk shows when no error is thrown.
+      if (count <= 0) {
+        fail("quota-exceeded");
+        return;
+      }
+      written += count;
+      offset += count;
+    }
+    open.flush();
+  } catch (error) {
+    // A partly written chunk still counts: `offset` follows the bytes that landed.
+    fail(failureOf(error));
+  }
+}
+
+let queue: Promise<void> = Promise.resolve();
+
+scope.addEventListener("message", (event) => {
+  const request = event.data;
+  queue = queue
+    .then(async () => {
+      if (finished) return;
+      switch (request.type) {
+        case "open":
+          await open(request);
+          return;
+        case "append":
+          append(request.chunk);
+          return;
+        case "close":
+          finished = true;
+          post({ type: "closed", size: closeFile() });
+          return;
+      }
+    })
+    .catch(() => {
+      if (!finished) fail("failed");
+    });
+});
diff --git a/apps/web/src/infrastructure/recording/writer/writer-protocol.ts b/apps/web/src/infrastructure/recording/writer/writer-protocol.ts
new file mode 100644
index 00000000..e8c2c062
--- /dev/null
+++ b/apps/web/src/infrastructure/recording/writer/writer-protocol.ts
@@ -0,0 +1,24 @@
+// TJ-ARCH-MOB-001 compliant
+
+/** Messages the page sends to the recording writer worker. */
+export type WriterRequest =
+  | { readonly type: "open"; readonly fileName: string; readonly lockName: string }
+  | { readonly type: "append"; readonly chunk: ArrayBuffer }
+  | { readonly type: "close" };
+
+/**
+ * Why the writer stopped. `quota-exceeded`: the browser refused more bytes (a write threw
+ * `QuotaExceededError` or wrote nothing). `storage-unavailable`: the file system could
+ * not be opened. `failed`: anything else.
+ */
+export type WriterFailure = "quota-exceeded" | "storage-unavailable" | "failed";
+
+/**
+ * Messages the worker sends back. After `failed` the file is already closed and the lock
+ * released: what was written is kept, `size` bytes of it. The worker then ignores every
+ * further request.
+ */
+export type WriterEvent =
+  | { readonly type: "opened" }
+  | { readonly type: "closed"; readonly size: number }
+  | { readonly type: "failed"; readonly reason: WriterFailure; readonly size: number };
